using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Quantum.Foundation;

internal sealed class OriginalRowSaturationDocument : IScribeDocumentDefinition
{
    private const string Owner = "D5/S3/Quantum/Foundation/OriginalRowSaturation.";

    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Both original ball saturations and full-domain least confirmation from the fixed-edge row",
        H("Both original ball saturations and full-domain least confirmation from the fixed-edge row"), Blocks(
            Paragraph(Text("V is an arbitrary finite dimensional real normed space, C a pointed cone, and u its original linear unit. Where stated, C is closed and generating and u is strictly positive on nonzero C. K is the entire normalized base and P its entire extreme locus. All original linear effects between zero and u are retained; the full confirming family F(p) includes u. Pure reciprocity exchanges only two pure endpoints. No mixed reciprocity, matrix specialization, weakPair, unit-width assumption or global uniform-fiber premise is used.")),
            Describe.Lean(DescribeId.Create("original-row-saturation"), DeclarationHandle.Create(Owner + "original_row_saturation"),
                H("Exact edge row forces both budgets and the same least ep"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Assume the complete arbitrary original V,C,u, with C closed and generating and u strictly positive, EB3, pure PR and Inj. Fix any pure p, any complete three-chart a of D(p), and ep with the entire full zero-confirming fiber A(p) exactly {ep}; this does not restrict F(p), which still contains u. Fix any unit v and actual pure q=a(v). PureEdgeRow(p,q) means: for every original pure s, there is an actual e in the entire F(p) with e(q)=0 and e(s)=T(p,s). This is precisely the fixed-edge attainment relation needed from the protected producer. The theorem does not prove that an actual collapse supplies it.")),
                    Paragraph(Text("Under that exact row premise, extensionBudget(a,w)=1 for every unit w in the arbitrary first chart; for every complete chart b of the actual D(q), extensionBudget(b,w)=1 for every unit w there. The conclusion also exports the coefficient-one-half comparison formula (1+inner(w,z))/2 on every mixed input in the first whole chart and in every whole chart of D(q), for every pure sphere label in each. Moreover T(p,x)=ep(x) for every original mixed x in the entire K, and ep(x)<=f(x) on all C for every original f in the entire F(p). The proof constructs k from the exact existing original_coordinates owner under the stated EB3, Inj and singleton assumptions. The complete fixed edge J gives the pure-row minimum. The positive-effect bridge produces actual old-antipode orthogonality and forces the first scale to 1/2. In the actual second whole ball, the two original orthogonal points p and the old antipode force its scale to 1/2 as well. The first full scale then makes every first-ball diameter orthogonal, giving rho=1 in every direction and eq<=g on all pure inputs. Each fixed f-ep extends its pure nonnegativity to all C; only then does minimum attainment identify T(p,x) on all mixed inputs. Pure choices are never pasted into an affine function. No actual-collapse theorem, topology conclusion or application-ready protected join is asserted."))), DescribeRole.Theorem))));
}
